/**
 * Thin client for the Founders AI REST API (plan Section 11). Path and parameter types come from the
 * OpenAPI document (`src/schema.ts`, regenerated by `pnpm --filter @founders/sdk generate`).
 *
 *   const fa = new FoundersAI({ apiKey: process.env.FOUNDERS_AI_API_KEY });
 *   const company = await fa.companies.get("com_…");
 *   for await (const r of fa.paginate((p) => fa.transactions.fundingRounds({ ...p, type: "Seed" }))) { … }
 *
 * - every result carries `$meta` (credits charged/remaining, request id, idempotent replay)
 * - 429 is retried after Retry-After; 5xx and network errors with exponential backoff (never 501)
 * - every POST carries an Idempotency-Key, so a retried request is never charged twice
 * - errors are typed (AuthenticationError, InsufficientCreditsError, NotFoundError, …)
 * Works anywhere `fetch` exists (Node 18+, Deno, Bun, browsers via your backend, edge runtimes).
 */
import { errorFor, FoundersAIError, type Problem } from "./errors";
import type { paths } from "./schema";

export const DEFAULT_BASE_URL = "https://founders-ai-app.vercel.app/api/v1";
export const SDK_VERSION = "0.1.0";

type Method = "get" | "post" | "patch" | "delete";
type Op<P extends keyof paths, M extends Method> = paths[P][M];
/** Paths that support method M. */
export type PathsFor<M extends Method> = { [P in keyof paths]: Op<P, M> extends { parameters: unknown } ? P : never }[keyof paths];
type Params<P extends keyof paths, M extends Method, K extends "path" | "query"> = Op<P, M> extends { parameters: { [k in K]?: infer X } } ? X : never;
type Body<P extends keyof paths, M extends Method> = Op<P, M> extends { requestBody?: { content: { "application/json": infer B } } } ? B : never;

export type RequestOptions<P extends keyof paths, M extends Method> = {
  path?: Params<P, M, "path">;
  query?: Params<P, M, "query">;
  body?: Body<P, M>;
  /** Defaults to a random key on POST; reuse your own to make a retry across processes safe. */
  idempotencyKey?: string;
  signal?: AbortSignal;
};

export type ResponseMeta = { status: number; creditsCharged: number | null; creditsRemaining: number | null; requestId: string | null; replayed: boolean };
export type Json = Record<string, unknown>;
/** The JSON body plus a non-enumerable `$meta` (so it never leaks into JSON.stringify). */
export type Result<T = Json> = T & { readonly $meta: ResponseMeta };
export type Page<T = Json> = { items: T[]; next_cursor?: string | null; [k: string]: unknown };
export type PageParams = { limit?: number; cursor?: string };

export type FetchLike = (input: string, init: RequestInit) => Promise<Response>;

export type ClientOptions = {
  apiKey?: string;
  baseUrl?: string;
  maxRetries?: number;
  timeoutMs?: number;
  fetch?: FetchLike;
  /** Sleep used between retries (tests pass a no-op). */
  sleep?: (ms: number) => Promise<void>;
};

const env = (k: string): string | undefined => (typeof process !== "undefined" ? process.env?.[k] : undefined);
const toQuery = (q: Record<string, unknown> | undefined) => {
  const out = new URLSearchParams();
  for (const [k, v] of Object.entries(q ?? {})) {
    if (v === undefined || v === null) continue;
    out.set(k, Array.isArray(v) ? v.join(",") : typeof v === "boolean" ? (v ? "true" : "false") : String(v));
  }
  const s = out.toString();
  return s ? `?${s}` : "";
};
const num = (v: string | null) => (v == null || v === "" || Number.isNaN(Number(v)) ? null : Number(v));
const uuid = () => (globalThis.crypto?.randomUUID ? globalThis.crypto.randomUUID() : `${Date.now()}-${Math.random().toString(16).slice(2)}`);

export class FoundersAI {
  readonly baseUrl: string;
  private readonly apiKey: string;
  private readonly maxRetries: number;
  private readonly timeoutMs: number;
  private readonly fetchImpl: FetchLike;
  private readonly sleep: (ms: number) => Promise<void>;

  readonly companies: Companies;
  readonly people: People;
  readonly investors: Investors;
  readonly transactions: Transactions;
  readonly signals: Signals;
  readonly search: Search;
  readonly searches: SavedSearches;
  readonly lists: Lists;
  readonly network: Network;
  readonly account: Account;
  readonly webhooks: Webhooks;

  constructor(opts: ClientOptions = {}) {
    const key = opts.apiKey ?? env("FOUNDERS_AI_API_KEY");
    if (!key) throw new FoundersAIError("Pass apiKey or set FOUNDERS_AI_API_KEY");
    this.apiKey = key;
    this.baseUrl = (opts.baseUrl ?? env("FOUNDERS_AI_BASE_URL") ?? DEFAULT_BASE_URL).replace(/\/+$/, "");
    this.maxRetries = opts.maxRetries ?? 3;
    this.timeoutMs = opts.timeoutMs ?? 30_000;
    this.fetchImpl = opts.fetch ?? ((i, init) => fetch(i, init));
    this.sleep = opts.sleep ?? ((ms) => new Promise((r) => setTimeout(r, ms)));
    this.companies = new Companies(this);
    this.people = new People(this);
    this.investors = new Investors(this);
    this.transactions = new Transactions(this);
    this.signals = new Signals(this);
    this.search = new Search(this);
    this.searches = new SavedSearches(this);
    this.lists = new Lists(this);
    this.network = new Network(this);
    this.account = new Account(this);
    this.webhooks = new Webhooks(this);
  }

  /* ------------------------------------------------------------ typed transport */

  get<P extends PathsFor<"get">, T = Json>(path: P, opts?: RequestOptions<P, "get">) {
    return this.request<T>("GET", path, opts as RawOptions);
  }
  post<P extends PathsFor<"post">, T = Json>(path: P, opts?: RequestOptions<P, "post">) {
    return this.request<T>("POST", path, opts as RawOptions);
  }
  patch<P extends PathsFor<"patch">, T = Json>(path: P, opts?: RequestOptions<P, "patch">) {
    return this.request<T>("PATCH", path, opts as RawOptions);
  }
  delete<P extends PathsFor<"delete">, T = Json>(path: P, opts?: RequestOptions<P, "delete">) {
    return this.request<T>("DELETE", path, opts as RawOptions);
  }

  /** Untyped escape hatch with the same retries, idempotency and errors. */
  async request<T = Json>(method: string, pathTemplate: string, opts: RawOptions = {}): Promise<Result<T>> {
    const path = pathTemplate.replace(/\{(\w+)\}/g, (_, k: string) => {
      const v = opts.path?.[k];
      if (v === undefined || v === "") throw new FoundersAIError(`Missing path parameter "${k}" for ${pathTemplate}`);
      return encodeURIComponent(String(v));
    });
    const url = `${this.baseUrl}${path}${toQuery(opts.query)}`;
    const headers: Record<string, string> = { "X-API-Key": this.apiKey, Accept: "application/json", "X-Client": `founders-ai-ts/${SDK_VERSION}` };
    const body = opts.body === undefined ? undefined : JSON.stringify(opts.body);
    if (body !== undefined) headers["Content-Type"] = "application/json";
    if (method === "POST") headers["Idempotency-Key"] = opts.idempotencyKey ?? `ts-${uuid()}`;

    for (let attempt = 0; ; attempt++) {
      let res: Response;
      const ctrl = new AbortController();
      const timer = setTimeout(() => ctrl.abort(), this.timeoutMs);
      const onAbort = () => ctrl.abort();
      opts.signal?.addEventListener("abort", onAbort, { once: true });
      try {
        res = await this.fetchImpl(url, { method, headers, body, signal: ctrl.signal });
      } catch (e) {
        if (opts.signal?.aborted) throw e;
        if (attempt < this.maxRetries) {
          await this.sleep(backoff(attempt + 1, null));
          continue;
        }
        throw new FoundersAIError(`Network error calling ${method} ${path}: ${e instanceof Error ? e.message : String(e)}`);
      } finally {
        clearTimeout(timer);
        opts.signal?.removeEventListener("abort", onAbort);
      }
      const text = await res.text();
      if (res.ok) return withMeta<T>(text, res);
      const retryable = (res.status === 429 || res.status >= 500) && res.status !== 501;
      if (retryable && attempt < this.maxRetries) {
        await this.sleep(backoff(attempt + 1, res.headers.get("Retry-After")));
        continue;
      }
      let problem: Problem;
      try {
        problem = text ? (JSON.parse(text) as Problem) : {};
      } catch {
        problem = { title: text.slice(0, 200) };
      }
      throw errorFor(res.status, problem, res.headers.get("X-Request-Id"));
    }
  }

  /**
   * Every item of a cursor-paginated endpoint: `fetchPage` receives `{ limit, cursor }`.
   *   for await (const s of fa.paginate((p) => fa.signals.talent({ ...p, min_score: 8 }))) …
   */
  async *paginate<T = Json>(fetchPage: (p: Required<Pick<PageParams, "limit">> & PageParams) => Promise<Result<Page<T>>>, opts: { limit?: number; maxItems?: number } = {}): AsyncGenerator<T> {
    let cursor: string | undefined;
    let seen = 0;
    for (;;) {
      const page = await fetchPage({ limit: opts.limit ?? 100, ...(cursor ? { cursor } : {}) });
      for (const item of page.items ?? []) {
        yield item;
        if (opts.maxItems !== undefined && ++seen >= opts.maxItems) return;
      }
      cursor = page.next_cursor ?? undefined;
      if (!cursor) return;
    }
  }
}

type RawOptions = { path?: Record<string, unknown>; query?: Record<string, unknown>; body?: unknown; idempotencyKey?: string; signal?: AbortSignal };

function backoff(attempt: number, retryAfter: string | null): number {
  const s = retryAfter == null ? NaN : Number(retryAfter);
  if (Number.isFinite(s) && s >= 0) return s * 1000;
  return Math.min(8000, 500 * 2 ** (attempt - 1)) + Math.random() * 250;
}

function withMeta<T>(text: string, res: Response): Result<T> {
  const parsed: unknown = text ? JSON.parse(text) : {};
  const data = (parsed && typeof parsed === "object" && !Array.isArray(parsed) ? parsed : { items: parsed }) as T & object;
  const meta: ResponseMeta = {
    status: res.status,
    creditsCharged: num(res.headers.get("X-Credits-Charged")),
    creditsRemaining: num(res.headers.get("X-Credits-Remaining")),
    requestId: res.headers.get("X-Request-Id"),
    replayed: res.headers.get("Idempotent-Replayed") === "true",
  };
  Object.defineProperty(data, "$meta", { value: meta, enumerable: false });
  return data as Result<T>;
}

/* ------------------------------------------------------------------ resources */

type Q<P extends keyof paths> = Params<P, "get", "query">;
type B<P extends keyof paths, M extends Method = "post"> = Body<P, M>;

abstract class Resource {
  constructor(protected readonly c: FoundersAI) {}
}

class Companies extends Resource {
  get = (companyId: string) => this.c.get("/companies/{companyId}", { path: { companyId } });
  enrich = (items: B<"/companies">["items"]) => this.c.post("/companies", { body: { items } });
  resolve = (items: B<"/companies/resolve">["items"]) => this.c.post("/companies/resolve", { body: { items } });
  searchByText = (body: B<"/companies/search-by-text">) => this.c.post("/companies/search-by-text", { body });
  people = (companyId: string, query?: Q<"/companies/{companyId}/people">) => this.c.get<"/companies/{companyId}/people", Page>("/companies/{companyId}/people", { path: { companyId }, query });
  competitors = (companyId: string, query?: Q<"/companies/{companyId}/competitors">) => this.c.get<"/companies/{companyId}/competitors", Page>("/companies/{companyId}/competitors", { path: { companyId }, query });
  fundingRounds = (companyId: string, query?: Q<"/companies/{companyId}/funding-rounds">) => this.c.get<"/companies/{companyId}/funding-rounds", Page>("/companies/{companyId}/funding-rounds", { path: { companyId }, query });
  acquisitions = (companyId: string, query?: Q<"/companies/{companyId}/acquisitions">) => this.c.get<"/companies/{companyId}/acquisitions", Page>("/companies/{companyId}/acquisitions", { path: { companyId }, query });
  newsSignals = (companyId: string, query?: Q<"/companies/{companyId}/news-signals">) => this.c.get<"/companies/{companyId}/news-signals", Page>("/companies/{companyId}/news-signals", { path: { companyId }, query });
  ipos = (companyId: string) => this.c.get("/companies/{companyId}/ipos", { path: { companyId } });
  latestRevenue = (companyId: string) => this.c.get("/companies/{companyId}/latest-revenue", { path: { companyId } });
  latestValuation = (companyId: string) => this.c.get("/companies/{companyId}/latest-valuation", { path: { companyId } });
  revenueHistory = (companyId: string) => this.c.get("/companies/{companyId}/revenue-history", { path: { companyId } });
  traction = (companyId: string) => this.c.get("/companies/{companyId}/traction", { path: { companyId } });
  investorInterestSignals = (companyId: string, query?: Q<"/companies/{companyId}/investor-interest-signals">) =>
    this.c.get<"/companies/{companyId}/investor-interest-signals", Page>("/companies/{companyId}/investor-interest-signals", { path: { companyId }, query });
}

class People extends Resource {
  get = (personId: string) => this.c.get("/people/{personId}", { path: { personId } });
  enrich = (items: B<"/people">["items"]) => this.c.post("/people", { body: { items } });
  resolve = (items: B<"/people/resolve">["items"]) => this.c.post("/people/resolve", { body: { items } });
  byEmail = (email: string) => this.c.post("/people/by-email", { body: { email } });
  email = (personId: string) => this.c.get("/people/{personId}/email", { path: { personId } });
  talentSignals = (personId: string, query?: Q<"/people/{personId}/talent-signals">) => this.c.get<"/people/{personId}/talent-signals", Page>("/people/{personId}/talent-signals", { path: { personId }, query });
  experience = (personId: string) => this.c.get("/people/{personId}/experience", { path: { personId } });
  investments = (personId: string, query?: Q<"/people/{personId}/investments">) => this.c.get<"/people/{personId}/investments", Page>("/people/{personId}/investments", { path: { personId }, query });
}

class Investors extends Resource {
  get = (investorId: string) => this.c.get("/investors/{investorId}", { path: { investorId } });
  resolve = (items: B<"/investors/resolve">["items"]) => this.c.post("/investors/resolve", { body: { items } });
  portfolio = (investorId: string, query?: Q<"/investors/{investorId}/portfolio">) => this.c.get<"/investors/{investorId}/portfolio", Page>("/investors/{investorId}/portfolio", { path: { investorId }, query });
  fundingRounds = (investorId: string, query?: Q<"/investors/{investorId}/funding-rounds">) => this.c.get<"/investors/{investorId}/funding-rounds", Page>("/investors/{investorId}/funding-rounds", { path: { investorId }, query });
  coInvestors = (investorId: string, query?: Q<"/investors/{investorId}/co-investors">) => this.c.get<"/investors/{investorId}/co-investors", Page>("/investors/{investorId}/co-investors", { path: { investorId }, query });
  investorInterestSignals = (investorId: string, query?: Q<"/investors/{investorId}/investor-interest-signals">) =>
    this.c.get<"/investors/{investorId}/investor-interest-signals", Page>("/investors/{investorId}/investor-interest-signals", { path: { investorId }, query });
}

class Transactions extends Resource {
  fundingRounds = (query?: Q<"/funding-rounds">) => this.c.get<"/funding-rounds", Page>("/funding-rounds", { query });
  fundingRound = (roundId: string) => this.c.get("/funding-rounds/{roundId}", { path: { roundId } });
  acquisitions = (query?: Q<"/acquisitions">) => this.c.get<"/acquisitions", Page>("/acquisitions", { query });
  ipos = (query?: Q<"/ipos">) => this.c.get<"/ipos", Page>("/ipos", { query });
}

class Signals extends Resource {
  talent = (query?: Q<"/talent">) => this.c.get<"/talent", Page>("/talent", { query });
  talentSignal = (signalId: string) => this.c.get("/talent/{signalId}", { path: { signalId } });
  news = (query?: Q<"/news-signals">) => this.c.get<"/news-signals", Page>("/news-signals", { query });
  revenue = (query?: Q<"/revenue-signals">) => this.c.get<"/revenue-signals", Page>("/revenue-signals", { query });
  investorInterest = (query?: Q<"/investor-interest">) => this.c.get<"/investor-interest", Page>("/investor-interest", { query });
  investorInterestSignal = (signalId: string) => this.c.get("/investor-interest/{signalId}", { path: { signalId } });
}

class Search extends Resource {
  /** Plain-English search; page on with `results(query_id, { cursor })` (valid 7 days). */
  ai = (body: B<"/search">) => this.c.post<"/search", Page & { query_id: string }>("/search", { body });
  results = (queryId: string, query?: Q<"/search/{queryId}/results">) => this.c.get<"/search/{queryId}/results", Page>("/search/{queryId}/results", { path: { queryId }, query });
  extractEntities = (body: B<"/entities/extract">) => this.c.post("/entities/extract", { body });
  taxonomy = () => this.c.get("/taxonomy");
}

type SavedSearchProduct = "companies" | "people" | "investors" | "talent" | "transactions";

class SavedSearches extends Resource {
  list = () => this.c.get<"/searches", Page>("/searches");
  create = (body: B<"/searches">) => this.c.post("/searches", { body });
  get = (searchId: string) => this.c.get("/searches/{searchId}", { path: { searchId } });
  update = (searchId: string, body: B<"/searches/{searchId}", "patch">) => this.c.patch("/searches/{searchId}", { path: { searchId }, body });
  delete = (searchId: string) => this.c.delete("/searches/{searchId}", { path: { searchId } });
  results = (product: SavedSearchProduct, searchId: string, query?: Q<"/searches/companies/{searchId}/results">) =>
    this.c.request<Page>("GET", `/searches/${product}/{searchId}/results`, { path: { searchId }, query });
}

type ListKind = "companies" | "people" | "investors";

class Lists extends Resource {
  list = (query?: Q<"/lists">) => this.c.get<"/lists", Page>("/lists", { query });
  create = (body: B<"/lists">) => this.c.post("/lists", { body });
  get = (listId: string) => this.c.get("/lists/{listId}", { path: { listId } });
  update = (listId: string, body: B<"/lists/{listId}", "patch">) => this.c.patch("/lists/{listId}", { path: { listId }, body });
  delete = (listId: string) => this.c.delete("/lists/{listId}", { path: { listId } });
  results = (kind: ListKind, listId: string, query?: Q<"/lists/companies/{listId}/results">) => this.c.request<Page>("GET", `/lists/${kind}/{listId}/results`, { path: { listId }, query });
  modify = (kind: ListKind, listId: string, change: { add?: string[]; remove?: string[] }) =>
    this.c.request("PATCH", `/lists/${kind}/{listId}`, { path: { listId }, body: { add: change.add ?? [], remove: change.remove ?? [] } });
}

class Network extends Resource {
  people = (query?: Q<"/network/people">) => this.c.get<"/network/people", Page>("/network/people", { query });
  companies = (query?: Q<"/network/companies">) => this.c.get<"/network/companies", Page>("/network/companies", { query });
  connection = (personId: string) => this.c.get("/network/connection/{personId}", { path: { personId } });
  members = () => this.c.get("/network/members");
}

class Account extends Resource {
  credits = () => this.c.get("/organization/credits");
  usage = (query?: Q<"/organization/usage">) => this.c.get("/organization/usage", { query });
  me = () => this.c.get("/me");
}

class Webhooks extends Resource {
  list = () => this.c.get<"/webhooks", Page>("/webhooks");
  create = (body: B<"/webhooks">) => this.c.post<"/webhooks", Json & { id: string; secret: string }>("/webhooks", { body });
  delete = (webhookId: string) => this.c.delete("/webhooks/{webhookId}", { path: { webhookId } });
  test = (webhookId: string) => this.c.post("/webhooks/{webhookId}/test", { path: { webhookId } });
}
